1	<script setup lang="ts">
2	import { computed, defineAsyncComponent, ref, shallowRef, watch } from "vue";
3	import { useData } from "vitepress";
4	
5	// ── Types ──────────────────────────────────────────────────────────────────────
6	interface InstUiEntry {
7	  name: string;
8	  source: "custom" | "lucide";
9	  path: string;
10	  viewBox: string;
11	}
12	interface SimpleIconEntry {
13	  slug: string;
14	  title: string;
15	}
16	
17	// ── i18n ───────────────────────────────────────────────────────────────────────
18	const { theme } = useData();
19	const t = computed(() => {
20	  const base = {
21	    tabInstui: "InstUI icons",
22	    tabSimple: "Simple Icons",
23	    searchPlaceholder: "Filter icons…",
24	    allIcons: "All icons",
25	    tokenSheetLabel: "Token sheet",
26	    tokenLean: "Lean (no icons, ~23 KB gzip)",
27	    tokenFull: "Full (all icons, ~140 KB gzip)",
28	    formatLabel: "Output",
29	    formatLink: "<link>",
30	    formatImport: "@import",
31	    formatEsm: "ESM snippet",
32	    copy: "Copy",
33	    copied: "Copied",
34	    empty: "Select one or more icons to build a URL.",
35	    loadingNote: "Loading icon list…",
36	  };
37	  return { ...base, ...(theme.value as Record<string, unknown>).iconPicker };
38	});
39	
40	// ── Manifest (lazy, split by tab) ─────────────────────────────────────────────
41	const activeTab = ref<"instui" | "simple">("instui");
42	const instuiIcons = shallowRef<InstUiEntry[] | null>(null);
43	const simpleIcons = shallowRef<SimpleIconEntry[] | null>(null);
44	const loading = ref(false);
45	const loadError = ref(false);
46	
47	async function loadInstui(): Promise<void> {
48	  if (instuiIcons.value || loading.value) return;
49	  loading.value = true;
50	  loadError.value = false;
51	  try {
52	    const data = (await import("../generated/cdn-icon-manifest-instui.json")) as InstUiEntry[];
53	    instuiIcons.value = Array.isArray(data) ? data : (data as { default: InstUiEntry[] }).default;
54	  } catch {
55	    loadError.value = true;
56	  } finally {
57	    loading.value = false;
58	  }
59	}
60	
61	async function loadSimple(): Promise<void> {
62	  if (simpleIcons.value || loading.value) return;
63	  loading.value = true;
64	  loadError.value = false;
65	  try {
66	    const data = (await import("../generated/cdn-icon-manifest-simple.json")) as SimpleIconEntry[];
67	    simpleIcons.value = Array.isArray(data)
68	      ? data
69	      : (data as { default: SimpleIconEntry[] }).default;
70	  } catch {
71	    loadError.value = true;
72	  } finally {
73	    loading.value = false;
74	  }
75	}
76	
77	watch(
78	  activeTab,
79	  (tab) => {
80	    if (tab === "instui") void loadInstui();
81	    else void loadSimple();
82	  },
83	  { immediate: true },
84	);
85	
86	// ── Selection ─────────────────────────────────────────────────────────────────
87	const selectedInstui = ref<Set<string>>(new Set());
88	const selectedSimple = ref<Set<string>>(new Set());
89	const allInstui = ref(false);
90	const tokenSheet = ref<"lean" | "full">("lean");
91	const format = ref<"link" | "import" | "esm">("link");
92	const copied = ref(false);
93	const search = ref("");
94	
95	function toggleInstui(name: string): void {
96	  const next = new Set(selectedInstui.value);
97	  if (next.has(name)) next.delete(name);
98	  else next.add(name);
99	  selectedInstui.value = next;
100	  copied.value = false;
101	}
102	function toggleSimple(slug: string): void {
103	  const next = new Set(selectedSimple.value);
104	  if (next.has(slug)) next.delete(slug);
105	  else next.add(slug);
106	  selectedSimple.value = next;
107	  copied.value = false;
108	}
109	
110	const filteredInstui = computed(() => {
111	  const all = instuiIcons.value ?? [];
112	  const q = search.value.trim().toLowerCase();
113	  return q ? all.filter((i) => i.name.includes(q)) : all;
114	});
115	const filteredSimple = computed(() => {
116	  const all = simpleIcons.value ?? [];
117	  const q = search.value.trim().toLowerCase();
118	  return q ? all.filter((i) => i.slug.includes(q) || i.title.toLowerCase().includes(q)) : all;
119	});
120	
121	const hasSelection = computed(() =>
122	  activeTab.value === "instui"
123	    ? allInstui.value || selectedInstui.value.size > 0
124	    : selectedSimple.value.size > 0,
125	);
126	
127	// ── URL builder ───────────────────────────────────────────────────────────────
128	const c = "npm/@pantoken/components/dist";
129	const si = "npm/@pantoken/plugin-simple-icons/dist";
130	
131	const combineUrl = computed(() => {
132	  if (activeTab.value === "instui") {
133	    if (allInstui.value) {
134	      // Full instui icon set is already in the full token sheet; for lean, icons.css has all glyphs.
135	      return tokenSheet.value === "lean" ? `https://cdn.jsdelivr.net/combine/${c}/icons.css` : null;
136	    }
137	    const names = [...selectedInstui.value];
138	    if (names.length === 0) return null;
139	    const files = names.map((n) => `${c}/icons/${n}.css`);
140	    return `https://cdn.jsdelivr.net/combine/${files.join(",")}`;
141	  } else {
142	    const slugs = [...selectedSimple.value];
143	    if (slugs.length === 0) return null;
144	    const files = slugs.map((s) => `${si}/icons/${s}.css`);
145	    return `https://cdn.jsdelivr.net/combine/${files.join(",")}`;
146	  }
147	});
148	
149	const esmSnippet = computed(() => {
150	  if (activeTab.value === "instui") {
151	    if (allInstui.value) {
152	      return `import "https://esm.sh/@pantoken/components/icons.css";`;
153	    }
154	    const names = [...selectedInstui.value];
155	    if (names.length === 0) return null;
156	    return names
157	      .map((n) => `import "https://esm.sh/@pantoken/components/icons/${n}.css";`)
158	      .join("\n");
159	  } else {
160	    const slugs = [...selectedSimple.value];
161	    if (slugs.length === 0) return null;
162	    return slugs
163	      .map((s) => `import "https://esm.sh/@pantoken/plugin-simple-icons/icons/${s}.css";`)
164	      .join("\n");
165	  }
166	});
167	
168	const output = computed(() => {
169	  if (format.value === "esm") return esmSnippet.value ?? "";
170	  const url = combineUrl.value;
171	  if (!url) return "";
172	  return format.value === "link"
173	    ? `<link rel="stylesheet" href="${url}">`
174	    : `@import url("${url}");`;
175	});
176	
177	async function copy(): Promise<void> {
178	  try {
179	    await navigator.clipboard.writeText(output.value);
180	    copied.value = true;
181	    setTimeout(() => (copied.value = false), 1500);
182	  } catch {
183	    // Clipboard blocked — the code stays selectable.
184	  }
185	}
186	</script>
187	
