189	  <div
190	    class="icon-picker instui-view -background-secondary -border-radius-large -border-width-small instui-p-md"
191	  >
192	    <!-- Source tabs -->
193	    <div class="instui-tabs icon-picker__tabs" role="tablist">
194	      <button
195	        class="instui-button"
196	        :class="{ '-color-secondary': activeTab !== 'instui' }"
197	        role="tab"
198	        :aria-selected="activeTab === 'instui'"
199	        @click="activeTab = 'instui'"
