220	    >
221	      <!-- InstUI icons -->
222	      <template v-if="activeTab === 'instui'">
223	        <fieldset class="instui-form-field-group icon-picker__group">
224	          <legend class="instui-text -size-small">{{ t.tabInstui }}</legend>
225	          <label class="instui-checkbox icon-picker__all">
