264	      </template>
265	
266	      <!-- Simple Icons -->
267	      <template v-else>
268	        <fieldset class="instui-form-field-group icon-picker__group">
269	          <legend class="instui-text -size-small">{{ t.tabSimple }}</legend>
270	          <input
