272	            type="search"
273	            class="instui-text-input icon-picker__search"
274	            :placeholder="t.searchPlaceholder"
275	            aria-label="Filter icons"
276	          />
277	          <div
278	            class="icon-picker__grid instui-view -background-primary -border-radius-medium -border-width-small instui-p-sm"
