296	                loading="lazy"
297	                aria-hidden="true"
298	              />
299	              <span class="icon-picker__label">{{ icon.title }}</span>
300	            </label>
301	          </div>
302	        </fieldset>
303	      </template>
304	    </template>
305	
306	    <!-- Output format -->
307	    <div class="icon-picker__options">
308	      <fieldset class="instui-radio-input-group">
309	        <legend>{{ t.formatLabel }}</legend>
310	        <label class="instui-radio -variant-toggle">
311	          <input type="radio" name="icon-format" value="link" v-model="format" />
312	          <span>{{ t.formatLink }}</span>
