1	/**
2	 * @component form-field
3	 * @summary A form-field wrapper: a label, its controls, and inline, required, or readonly layouts.
4	 * @remarks An error message stays hidden until the field's control is `:user-invalid` (after the user interacts) or you add the `-invalid` class. Use `-layout-inline` to put the label beside the controls and `-layout-stacked` to put it above.
5	 * @modifier -inline — Inline layout (shorthand for `-layout-inline`).
6	 * @modifier -layout-inline — Inline layout: label beside the controls.
7	 * @modifier -layout-stacked — Stacked layout: label above the controls.
8	 * @modifier -label-align-start — Start-align the label text.
9	 * @modifier -label-align-end — End-align the label text.
10	 * @modifier -invalid — Invalid (error) state.
11	 * @modifier -readonly — Read-only state.
12	 * @modifier -v-align-top — Top-align the label with the controls.
13	 * @modifier -v-align-bottom — Bottom-align the label with the controls.
14	 * @part .label — The field label.
15	 * @part .controls — The control area beside or below the label.
16	 * @pseudo ::after — Renders the decorative required-field asterisk after the label text when the field is required.
17	 * @accessibility The `<label>` element wraps the control, so the label text names it natively; the required asterisk is decorative and should be hidden from assistive tech (aria-hidden), and the error message surfaces once the control is `:user-invalid` or you add the `-invalid` class.
18	 * @compat Contains its element styles with the CSS `@scope` at-rule; needs a recent Chromium, Firefox, or Safari.
19	 * @example
20	 * <label class="pfx-form-field">
21	 *   <span class="label">Email address</span>
22	 *   <span class="controls"><input class="pfx-text-input" type="email" placeholder="you@example.com"></span>
23	 *   <div class="pfx-form-field-messages">
24	 *     <span class="pfx-form-field-message -type-hint">We'll never share it.</span>
25	 *     <span class="pfx-form-field-message -type-error">Enter a valid email address.</span>
26	 *   </div>
27	 * </label>
28	 * @structure
29	 * .pfx-form-field {
30	 *   .label {}
31	 *   .controls {
32	 *     .pfx-text-input {}
33	 *   }
34	 *   .pfx-form-field-messages {}
35	 * }
36	 * @related form-field-messages — Renders the field's hint, error, and success messages.
37	 * @related form-field-group — Groups related fields under a shared legend.
38	 */
39	.pfx-form-field {
40	  display: grid;
41	  grid-template-columns: 1fr;
42	  grid-template-areas: "label" "controls" "messages";
43	  gap: var(--instui-component-form-field-layout-gap-inputs);
44	  color: var(--instui-component-form-field-layout-text-color);
45	  font-family: var(--instui-component-form-field-layout-font-family);
46	}
47	@scope (.pfx-form-field) {
48	  :scope > .label {
49	    grid-area: label;
50	    color: var(--instui-component-form-field-layout-text-color);
51	    font-family: var(--instui-component-form-field-layout-font-family);
52	    font-weight: var(--instui-component-form-field-layout-font-weight);
53	    font-size: var(--instui-component-form-field-layout-font-size);
54	    line-height: var(--instui-component-form-field-layout-line-height);
55	  }
56	  :scope > .controls {
57	    grid-area: controls;
58	  }
59	}
60	/* Messages region — kept OUTSIDE @scope: the messages class shares the form-field prefix. */
61	.pfx-form-field > .pfx-form-field-messages {
62	  grid-area: messages;
63	}
64	/* Client-side validation: an error message stays hidden until the field's control is :user-invalid
65	   (after the user has interacted), per MDN guidance; then it shows. The explicit -invalid class on the
66	   control (and a standalone .instui-form-field-messages outside a field) are unaffected. */
67	.pfx-form-field .pfx-form-field-message.-type-error,
68	.pfx-form-field .pfx-form-field-message.-type-new-error {
69	  display: none;
70	}
