72	.pfx-form-field:has(:user-invalid) .pfx-form-field-message.-type-new-error,
73	.pfx-form-field.-invalid .pfx-form-field-message.-type-error,
74	.pfx-form-field.-invalid .pfx-form-field-message.-type-new-error {
75	  display: inline-flex;
76	}
