1	/**
2	 * Emit two icon picker manifests for the `<IconPicker />` docs component:
3	 *   - `cdn-icon-manifest-instui.json`: every icon from `@pantoken/icons` (~335 KB raw, ~120 KB gzip)
4	 *   - `cdn-icon-manifest-simple.json`: every brand slug from `simple-icons` (~4.7 MB raw, ~1.8 MB gzip)
5	 *
6	 * Split so each picker tab lazy-loads only what it needs. Uses only the `<path d="…">` data rather
7	 * than full SVG markup to keep the files compact. Wired into `docs:assets`.
8	 */
9	import { mkdirSync, writeFileSync } from "node:fs";
10	import { resolve } from "node:path";
11	import { icons } from "../../formats/icons/src/index.ts";
12	import { defaultRegistry } from "../../plugins/pantoken/simple-icons/src/index.ts";
13	
14	// Extract the first <path d="…"> from inline SVG markup.
15	function extractPath(svg: string): string {
16	  return /\sd="([^"]+)"/.exec(svg)?.[1] ?? "";
17	}
18	
19	const outDir = resolve(import.meta.dirname, "../.vitepress/theme/generated");
20	mkdirSync(outDir, { recursive: true });
21	
22	// ── InstUI manifest ──────────────────────────────────────────────────────────
23	const instui = icons.map((icon) => ({
24	  name: icon.name,
25	  source: icon.source ?? "lucide",
26	  path: extractPath(icon.svg),
27	  viewBox: icon.viewBox ?? "0 0 24 24",
28	}));
29	const instuiOut = resolve(outDir, "cdn-icon-manifest-instui.json");
30	writeFileSync(instuiOut, `${JSON.stringify(instui, null, 2)}\n`);
31	console.log(`✓ docs: wrote cdn-icon-manifest-instui.json (${instui.length} icons)`);
32	
33	// ── Simple Icons manifest ────────────────────────────────────────────────────
34	// Slug + title only (no path data) — icons are previewed via a jsDelivr CDN img src in the picker.
35	const registry = await defaultRegistry();
36	const simpleIcons = Object.values(registry)
37	  .filter(
38	    (v): v is { title: string; slug: string } =>
39	      !!v &&
40	      typeof (v as { slug?: unknown }).slug === "string" &&
41	      typeof (v as { title?: unknown }).title === "string",
42	  )
43	  .map((v) => ({ slug: v.slug, title: v.title }))
44	  .sort((a, b) => a.slug.localeCompare(b.slug));
45	const simpleOut = resolve(outDir, "cdn-icon-manifest-simple.json");
46	writeFileSync(simpleOut, `${JSON.stringify(simpleIcons, null, 2)}\n`);
47	console.log(`✓ docs: wrote cdn-icon-manifest-simple.json (${simpleIcons.length} icons)`);
