// "All icons" is a tri-state checkbox over the InstUI list (Simple Icons has no bundled equivalent):
// checked when every InstUI icon is selected, indeterminate when some are, unchecked when none are.
// It selects/clears the list without disabling the individual checkboxes.
const allInstuiCheckboxEl = ref<HTMLInputElement | null>(null);
const allInstuiSelected = computed(
  () => (instuiIcons.value?.length ?? 0) > 0 && selectedInstui.value.size === instuiIcons.value?.length,
);
const someInstuiSelected = computed(
  () => selectedInstui.value.size > 0 && !allInstuiSelected.value,
);
watchEffect(() => {
  if (allInstuiCheckboxEl.value) allInstuiCheckboxEl.value.indeterminate = someInstuiSelected.value;
});
function toggleAllInstui(checked: boolean): void {
