/**
 * Emit the CDN picker manifest the `<WebComponentsPicker />` docs component reads: every base element
 * name `@pantoken/web-components` registers. Sourced from the package's own `ELEMENTS` list — never
 * hand-maintained. Safe to import at build time: the module only touches `HTMLElement` inside
 * `register()`, a no-op without a DOM (see its own module doc comment).
 *
 * Wired into `docs:assets`, so it regenerates for both `docs:dev` and `docs:build`.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { ELEMENTS } from "../../renderers/web-components/src/index.ts";

const elements = ELEMENTS.map((name) => ({ name }));

const out = resolve(
  import.meta.dirname,
  "../.vitepress/theme/generated/cdn-web-components-manifest.json",
);
mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, `${JSON.stringify(elements, null, 2)}\n`);
console.log(`✓ docs: wrote cdn-web-components-manifest.json (${elements.length} elements)`);

