251	/**
252	 * Build the `command`-event router: forward a target's `command` events to a handler, and where the
253	 * Invoker Commands API is missing, delegate matching `commandfor` clicks across the target's tree.
254	 */
255	function makeOnCommand(invokerSupported: boolean): RegisterContext["onCommand"] {
256	  // Elements call onCommand from paint()/connectedCallback and may re-run it (calendar re-wires its
257	  // recreated internal grid on every paint). Adding a fresh listener each time would accumulate, so one
258	  // click fires N times. Wire each target's `command` listener once (keyed on the target object — a
259	  // recreated target is a new object, its predecessor GC'd), and register ONE click-fallback delegate
260	  // per (root, id) that dispatches to the LATEST handler for that id. That fixes calendar's repeated
261	  // re-wire (stable id `cal`) and a same-id host recreated later, without the stale-handler capture a
262	  // plain skip-after-first would cause; distinct ids on a shared document each get their own routing.
263	  type CommandHandler = (command: string, source: Element | null) => void;
264	  // Latest handler per target object (WeakMap → recreated targets GC away); command listener wired once
265	  // per target; one click-fallback delegate per root. The delegate resolves `commandfor` to the LIVE
266	  // element and its current handler at click time, so it survives a target whose id is set after wiring
267	  // (drilldown) and a repainted grid that swaps its element (calendar) — without accumulating listeners.
268	  const handlerByTarget = new WeakMap<Element, CommandHandler>();
269	  const wiredTargets = new WeakSet<EventTarget>();
270	  const delegatedScopes = new WeakSet<EventTarget>();
271	  return (target, handler) => {
272	    handlerByTarget.set(target, handler);
273	    if (!wiredTargets.has(target)) {
274	      wiredTargets.add(target);
275	      target.addEventListener("command", (event) => {
276	        const ce = event as CommandEventish;
277	        handlerByTarget.get(target)?.(ce.command, ce.source);
278	      });
279	    }
280	    if (invokerSupported) return;
281	    // Fallback for browsers without the API: delegate clicks across the target's tree — its shadow root
282	    // for an internal grid, or the document for a light-DOM host — matching on `commandfor`, so
283	    // `command` buttons keep working wherever they live.
284	    const scope = target.getRootNode() as Document | ShadowRoot;
285	    if (delegatedScopes.has(scope)) return;
286	    delegatedScopes.add(scope);
287	    scope.addEventListener("click", (event) => {
288	      const el = event.target instanceof Element ? event.target : null;
289	      const button = el?.closest<HTMLButtonElement>("button[command][commandfor]");
290	      const forId = button?.getAttribute("commandfor");
291	      const routedTarget = forId ? scope.getElementById(forId) : null;
292	      const routed = routedTarget ? handlerByTarget.get(routedTarget) : undefined;
293	      if (button && routed) routed(button.getAttribute("command") ?? "", button);
294	    });
295	  };
