309	        static observedAttributes = [
310	          "variant",
311	          "size",
312	          "shape",
313	          "value",
314	          "max",
315	          "label",
316	          "pressed",
317	          "lines",
318	          "placement",
319	          "minimized",
320	          "constrain",
321	          "src",
322	          "alt",
323	          "tip",
324	          "has-shadow",
