384	  target: ElementRegistry | undefined = globalThis.customElements,
385	  options: {
386	    prefix?: string | null;
387	    only?: readonly string[];
388	    locale?: string;
389	    strings?: Partial<WebComponentStrings>;
390	    dir?: "ltr" | "rtl";
391	  } = {},
392	): void {
393	  if (!target || typeof HTMLElement === "undefined") return;
394	
395	  // When `only` is given, expand it through the nested-render dependencies and define just that set;
396	  // otherwise define every element. The canonical `DEFINITIONS` order is preserved either way, so a
397	  // nested dependency is always defined before the element that renders it.
398	  const wanted = options.only ? withNestedDeps(options.only) : null;
399	
400	  // Tag prefix: a valid non-empty string overrides the default; anything else (empty, whitespace, null,
401	  // omitted) falls back to `instui`. A prefix is always applied because a custom-element name MUST contain
402	  // a hyphen — `<icon>` is invalid, `<instui-icon>`/`<x-icon>` are not. The inlined `.instui-*` CSS classes
403	  // are an internal detail and are NOT affected by this — only the custom-element tag name.
404	  const prefix = resolvePrefix(options.prefix);
405	  const tag = (base: string): string => `${prefix}-${base}`;
406	  // Route every internal `registry.get`/`define` (all keyed on the canonical `instui-<base>` names)
407	  // through the active prefix.
408	  const registry = makeRegistry(target, tag);
409	
410	  // The shadow-DOM CSS is built with the default `instui` prefix so it matches the `instui-*` markup
411	  // in each element (the builders drop the prefix on a falsy value).
412	  const I = { prefix: "instui" } as const;
413	
414	  // The calendar and date picker drive navigation with the Invoker Commands API. `onCommand` routes a
415	  // target's `command` events to a handler; where the API is unavailable it delegates clicks on the
416	  // target's own `command`/`commandfor` buttons instead, so the buttons keep working everywhere.
417	  const INVOKER_SUPPORTED =
418	    typeof HTMLButtonElement !== "undefined" && "command" in HTMLButtonElement.prototype;
419	  const onCommand = makeOnCommand(INVOKER_SUPPORTED);
420	  const wrapper = makeWrapper(registry);
421	
422	  const locale = options.locale ?? "en";
423	  const dir = options.dir ?? "ltr";
424	  const strings = options.strings
425	    ? makeStrings(locale, options.strings)
426	    : locale === "en"
427	      ? ENGLISH_STRINGS
428	      : makeStrings(locale);
429	  const firstDay = resolveFirstDay(locale);
430	
431	  const ctx: RegisterContext = {
432	    registry,
433	    tag,
434	    I,
435	    invokerSupported: INVOKER_SUPPORTED,
436	    onCommand,
437	    wrapper,
438	    variantClass,
439	    iconSvg,
440	    locale,
441	    dir,
442	    firstDay,
443	    strings,
444	  };
445	
446	  for (const def of DEFINITIONS) {
447	    if (wanted && !wanted.has(def.name)) continue;
448	    def.define(ctx);
449	  }
450	}
451	
452	// Auto-register in the browser; a no-op everywhere else.
453	register();
