11	export interface ElementRegistry {
12	  get(name: string): unknown;
13	  define(name: string, ctor: CustomElementConstructor): void;
14	}
15	
16	/** The `command`/`source` shape of an Invoker Commands `CommandEvent` (not yet in the DOM lib types). */
17	export interface CommandEventish extends Event {
18	  command: string;
19	  source: Element | null;
20	}
21	
22	/**
23	 * The shared state a `register()` call builds once and threads to every {@link ElementDefinition}.
24	 * It carries the prefix-aware registry adapter, the `tag()` helper for nested markup, the CSS-class
25	 * prefix `I`, the Invoker Commands support flag + router, the `wrapper`/`variantClass`/`iconSvg`
26	 * factories, and locale data (`strings`, `locale`, `dir`, `firstDay`).
27	 */
