29	  /** The scoped registry: rewrites `instui-<base>` → the active-prefix tag on `get`/`define`. */
30	  registry: ElementRegistry;
31	  /** Map a base name to the active-prefix tag (for nested markup, `querySelector`, `tagName`). */
32	  tag: (base: string) => string;
33	  /** The CSS-class prefix for the inlined component sheets — always `instui`, separate from the tag prefix. */
