35	  /** Whether the browser supports the Invoker Commands API (`command`/`commandfor`). */
36	  invokerSupported: boolean;
37	  /** Route a target's `command` events (or a click fallback) to a handler. */
38	  onCommand: (
39	    target: HTMLElement,
40	    handler: (command: string, source: Element | null) => void,
41	  ) => void;
42	  /** Define a shadow-DOM element: `<style>:host{display}css</style>` + markup from `render(host)`.
43	   * `invoker: true` forwards the host's `popovertarget`/`command` to the inner `<button>` (IDL). */
