45	    tag: string,
46	    css: string,
47	    render: (host: HTMLElement) => string,
48	    options?: { display?: string; invoker?: boolean },
49	  ) => void;
50	  /** Build a `.instui-<name>` class with an optional `-color-<variant>` modifier from `variant`. */
51	  variantClass: (name: string, host: HTMLElement) => string;
52	  /** Resolve an icon name to inline SVG (empty string when unknown). */
53	  iconSvg: (name: string) => string;
