66	  /** The base tag name, e.g. `button` (minted to `<instui-button>`/`<x-button>` by the active prefix). */
67	  readonly name: string;
68	  /** Register the element into `ctx.registry`, using only the shared, prefix-aware helpers. */
69	  define(ctx: RegisterContext): void;
70	}
