export function register(
  target: ElementRegistry | undefined = globalThis.customElements,
  options: {
    prefix?: string | null;
    only?: readonly string[];
    locale?: string;
    strings?: Partial<WebComponentStrings>;
    dir?: "ltr" | "rtl";
