219	 * against the host's root so a shadow-DOM button can drive a light-DOM `[popover]`/command target.
220	 */
221	function syncInvoker(host: HTMLElement): void {
222	  const btn = host.shadowRoot?.querySelector("button") as InvokerButton | null;
223	  if (!btn) return;
224	  const root = host.getRootNode() as Document | ShadowRoot;
225	  const byId = (id: string): Element | null =>
226	    typeof root.getElementById === "function" ? root.getElementById(id) : null;
227	  const popoverTarget = host.getAttribute("popovertarget");
228	  if (popoverTarget !== null) {
229	    btn.popoverTargetElement = byId(popoverTarget);
230	    btn.popoverTargetAction = host.getAttribute("popovertargetaction") ?? "toggle";
231	  }
232	  const commandFor = host.getAttribute("commandfor");
233	  const command = host.getAttribute("command");
234	  if (commandFor !== null && command !== null) {
235	    btn.commandForElement = byId(commandFor);
236	    btn.command = command;
237	  }
238	}
239	
240	/** Build a `.instui-<name>` class with an optional `-color-<variant>` key-value modifier from `variant`. */
241	function variantClass(name: string, host: HTMLElement): string {
242	  const variant = frag(host.getAttribute("variant"));
243	  return variant ? `instui-${name} -color-${variant}` : `instui-${name}`;
244	}
245	
246	/** Resolve the tag prefix: a non-empty string wins; anything empty/nullish falls back to `instui`. */
247	function resolvePrefix(prefix: string | null | undefined): string {
248	  return typeof prefix === "string" && prefix.trim() !== "" ? prefix : DEFAULT_PREFIX;
249	}
250	
251	/** Build the prefix-aware registry: rewrite every internal `instui-<base>` name to the active-prefix tag. */
252	function makeRegistry(host: ElementRegistry, tag: (base: string) => string): ElementRegistry {
253	  return {
254	    get: (name) => host.get(tag(name.replace(/^instui-/u, ""))),
255	    define: (name, ctor) => {
256	      const resolved = tag(name.replace(/^instui-/u, ""));
257	      // Wrap every element with the shared spacing mixin, so `margin`/`padding` (+ per-side) work
258	      // universally — no per-element code needed.
259	      if (!host.get(resolved)) host.define(resolved, withSpacing(ctor));
260	    },
261	  };
262	}
263	
264	/**
265	 * Build the `command`-event router: forward a target's `command` events to a handler, and where the
266	 * Invoker Commands API is missing, delegate matching `commandfor` clicks across the target's tree.
267	 */
268	function makeOnCommand(invokerSupported: boolean): RegisterContext["onCommand"] {
269	  // Elements call onCommand from paint()/connectedCallback and may re-run it (calendar re-wires its
270	  // recreated internal grid on every paint). Adding a fresh listener each time would accumulate, so one
271	  // click fires N times. Wire each target's `command` listener once (keyed on the target object — a
272	  // recreated target is a new object, its predecessor GC'd), and register ONE click-fallback delegate
273	  // per (root, id) that dispatches to the LATEST handler for that id. That fixes calendar's repeated
274	  // re-wire (stable id `cal`) and a same-id host recreated later, without the stale-handler capture a
275	  // plain skip-after-first would cause; distinct ids on a shared document each get their own routing.
276	  type CommandHandler = (command: string, source: Element | null) => void;
277	  // Latest handler per target object (WeakMap → recreated targets GC away); command listener wired once
278	  // per target; one click-fallback delegate per root. The delegate resolves `commandfor` to the LIVE
279	  // element and its current handler at click time, so it survives a target whose id is set after wiring
280	  // (drilldown) and a repainted grid that swaps its element (calendar) — without accumulating listeners.
281	  const handlerByTarget = new WeakMap<Element, CommandHandler>();
282	  const wiredTargets = new WeakSet<EventTarget>();
283	  const delegatedScopes = new WeakSet<EventTarget>();
284	  return (target, handler) => {
285	    handlerByTarget.set(target, handler);
286	    if (!wiredTargets.has(target)) {
287	      wiredTargets.add(target);
288	      target.addEventListener("command", (event) => {
289	        const ce = event as CommandEventish;
290	        handlerByTarget.get(target)?.(ce.command, ce.source);
291	      });
292	    }
293	    if (invokerSupported) return;
294	    // Fallback for browsers without the API: delegate clicks across the target's tree — its shadow root
295	    // for an internal grid, or the document for a light-DOM host — matching on `commandfor`, so
296	    // `command` buttons keep working wherever they live.
297	    const scope = target.getRootNode() as Document | ShadowRoot;
298	    if (delegatedScopes.has(scope)) return;
299	    delegatedScopes.add(scope);
300	    scope.addEventListener("click", (event) => {
301	      const el = event.target instanceof Element ? event.target : null;
302	      const button = el?.closest<HTMLButtonElement>("button[command][commandfor]");
303	      const forId = button?.getAttribute("commandfor");
304	      const routedTarget = forId ? scope.getElementById(forId) : null;
305	      const routed = routedTarget ? handlerByTarget.get(routedTarget) : undefined;
306	      if (button && routed) routed(button.getAttribute("command") ?? "", button);
307	    });
308	  };
309	}
310	
311	/**
312	 * Build the shadow-DOM element factory: define `<style>:host{display}css</style>` + `render(host)`
313	 * markup, wiring invoker forwarding when `invoker` is set. The `:host` display is explicit because a
314	 * custom element defaults to `display: inline`, which would collapse internal `width: 100%`.
315	 */
316	function makeWrapper(registry: ElementRegistry): RegisterContext["wrapper"] {
317	  return (tag, css, render, { display = "inline-block", invoker = false } = {}) => {
318	    if (registry.get(tag)) return;
319	    registry.define(
320	      tag,
321	      class extends HTMLElement {
322	        static observedAttributes = [
323	          "variant",
324	          "size",
325	          "shape",
326	          "value",
327	          "max",
328	          "label",
329	          "pressed",
330	          "lines",
331	          "placement",
332	          "minimized",
333	          "constrain",
334	          "src",
335	          "alt",
336	          "tip",
337	          "has-shadow",
338	          "popovertarget",
339	          "popovertargetaction",
340	          "command",
341	          "commandfor",
342	        ];
343	        constructor() {
344	          super();
345	          this.attachShadow({ mode: "open" });
346	        }
347	        connectedCallback(): void {
348	          this.paint();
349	          if (invoker) {
350	            // Re-resolve the target on each interaction: an id can point forward to an element parsed
351	            // after this button, and the target may be swapped at runtime. `requestAnimationFrame`
352	            // catches the initial forward reference once the document has finished parsing.
353	            const sync = (): void => syncInvoker(this);
354	            this.addEventListener("pointerdown", sync);
355	            this.addEventListener("keydown", sync);
356	            if (typeof requestAnimationFrame === "function") requestAnimationFrame(sync);
357	          }
358	        }
359	        attributeChangedCallback(): void {
360	          this.paint();
361	        }
362	        paint(): void {
363	          if (this.shadowRoot) {
364	            this.shadowRoot.innerHTML = `<style>:host{display:${display}}${css}</style>${render(this)}`;
365	            if (invoker) syncInvoker(this);
366	          }
367	        }
368	      },
369	    );
370	  };
371	}
372	
373	/** The options {@link register} and {@link buildRegisterContext} share (everything but `only`, which
374	 * only makes sense at the `register()` call site — `buildRegisterContext`'s callers decide their own
375	 * element subset directly). */
376	export interface RegisterContextOptions {
377	  prefix?: string | null;
378	  locale?: string;
379	  strings?: Partial<WebComponentStrings>;
380	  dir?: "ltr" | "rtl";
381	}
382	
383	/**
384	 * Build the shared {@link RegisterContext} a `register()`-style call threads to every element's
385	 * `define`. Factored out of {@link register} so the icon resolver is injectable: `register()` itself
386	 * always passes the real, `@pantoken/icons`-backed {@link iconSvg} (unchanged default behavior for
387	 * every existing caller), while the per-element CDN build passes {@link noopIconSvg} for elements that
388	 * never call it — `@pantoken/icons`/`@pantoken/tokens` is a multi-MB dependency, and since Rollup can't
389	 * code-split `iife`/`umd` output, anything statically reachable from `register()` ends up in every
390	 * bundle that uses it, regardless of whether that specific element's code path ever invokes it.
391	 *
392	 * @param options - Same shape as {@link register}'s options, minus `only`.
393	 * @param target - The registry to define into.
394	 * @param resolveIconSvg - The resolver wired into `ctx.iconSvg` — pass {@link iconSvg} for real icons
395	 *   or {@link noopIconSvg} when the caller's element set provably never renders one (see
396	 *   {@link ICON_ELEMENTS}).
397	 */
398	export function buildRegisterContext(
399	  options: RegisterContextOptions,
400	  target: ElementRegistry,
401	  resolveIconSvg: (name: string) => string,
402	): RegisterContext {
403	  // Tag prefix: a valid non-empty string overrides the default; anything else (empty, whitespace, null,
404	  // omitted) falls back to `instui`. A prefix is always applied because a custom-element name MUST contain
405	  // a hyphen — `<icon>` is invalid, `<instui-icon>`/`<x-icon>` are not. The inlined `.instui-*` CSS classes
406	  // are an internal detail and are NOT affected by this — only the custom-element tag name.
407	  const prefix = resolvePrefix(options.prefix);
408	  const tag = (base: string): string => `${prefix}-${base}`;
409	  // Route every internal `registry.get`/`define` (all keyed on the canonical `instui-<base>` names)
410	  // through the active prefix.
411	  const registry = makeRegistry(target, tag);
412	
413	  // The shadow-DOM CSS is built with the default `instui` prefix so it matches the `instui-*` markup
414	  // in each element (the builders drop the prefix on a falsy value).
415	  const I = { prefix: "instui" } as const;
416	
417	  // The calendar and date picker drive navigation with the Invoker Commands API. `onCommand` routes a
418	  // target's `command` events to a handler; where the API is unavailable it delegates clicks on the
419	  // target's own `command`/`commandfor` buttons instead, so the buttons keep working everywhere.
420	  const INVOKER_SUPPORTED =
421	    typeof HTMLButtonElement !== "undefined" && "command" in HTMLButtonElement.prototype;
422	  const onCommand = makeOnCommand(INVOKER_SUPPORTED);
423	  const wrapper = makeWrapper(registry);
424	
425	  const locale = options.locale ?? "en";
426	  const dir = options.dir ?? "ltr";
427	  const strings = options.strings
428	    ? makeStrings(locale, options.strings)
429	    : locale === "en"
430	      ? ENGLISH_STRINGS
431	      : makeStrings(locale);
432	  const firstDay = resolveFirstDay(locale);
433	
434	  return {
435	    registry,
436	    tag,
437	    I,
438	    invokerSupported: INVOKER_SUPPORTED,
439	    onCommand,
440	    wrapper,
441	    variantClass,
442	    iconSvg: resolveIconSvg,
443	    locale,
444	    dir,
445	    firstDay,
446	    strings,
447	  };
448	}
449	
450	/**
451	 * Register the pantoken custom elements. No-op when there is no DOM (SSR / build), so this module
452	 * is safe to import anywhere.
453	 *
454	 * @param target - The registry to define into (defaults to `globalThis.customElements`).
455	 * @param options - `prefix` sets the tag prefix, mirroring the CSS layer: pass a non-empty string like
456	 *   `x` for `<x-icon>`. A prefix is always applied (a custom-element name must contain a hyphen), so an
457	 *   omitted, empty, or nullish prefix falls back to the default `instui` (`<instui-icon>`). `only` limits
458	 *   registration to a subset of the `ELEMENTS` base names — its nested render dependencies are pulled in
459	 *   automatically, so `{ only: ["date-time-input"] }` also defines `date-input` and `calendar`. Omit
460	 *   `only` to register every element (the default).
461	 *
462	 * @example
463	 * ```ts
464	 * import { register } from "@pantoken/web-components";
465	 * import "@pantoken/css"; // defines the --instui-* custom properties the elements read
466	 *
467	 * register(); // <instui-button>, <instui-icon>, …
468	 * register(customElements, { prefix: "x" }); // <x-button>, <x-icon>, …
469	 * register(customElements, { only: ["button", "alert"] }); // just those two
470	 * register(customElements, { locale: "hu", strings: { back: "Vissza" } }); // localized
471	 * ```
472	 */
473	export function register(
474	  target: ElementRegistry | undefined = globalThis.customElements,
475	  options: RegisterContextOptions & { only?: readonly string[] } = {},
476	): void {
477	  if (!target || typeof HTMLElement === "undefined") return;
478	
479	  // When `only` is given, expand it through the nested-render dependencies and define just that set;
480	  // otherwise define every element. The canonical `DEFINITIONS` order is preserved either way, so a
481	  // nested dependency is always defined before the element that renders it.
482	  const wanted = options.only ? withNestedDeps(options.only) : null;
483	
484	  const ctx = buildRegisterContext(options, target, iconSvg);
485	
486	  for (const def of DEFINITIONS) {
487	    if (wanted && !wanted.has(def.name)) continue;
488	    def.define(ctx);
489	  }
490	}
491	
492	// Auto-register in the browser; a no-op everywhere else.
493	register();
