267	      tag,
268	      class extends HTMLElement {
269	        static observedAttributes = [
270	          "variant",
271	          "size",
272	          "shape",
273	          "value",
274	          "max",
275	          "label",
276	          "pressed",
277	          "lines",
278	          "placement",
279	          "minimized",
280	          "constrain",
281	          "src",
282	          "alt",
283	          "tip",
284	          "has-shadow",
285	          "popovertarget",
286	          "popovertargetaction",
