297	            // Re-resolve the target on each interaction: an id can point forward to an element parsed
298	            // after this button, and the target may be swapped at runtime. `requestAnimationFrame`
299	            // catches the initial forward reference once the document has finished parsing.
300	            const sync = (): void => syncInvoker(this);
301	            this.addEventListener("pointerdown", sync);
302	            this.addEventListener("keydown", sync);
303	            if (typeof requestAnimationFrame === "function") requestAnimationFrame(sync);
