320	/** The options {@link register} and {@link buildRegisterContext} share (everything but `only`, which
321	 * only makes sense at the `register()` call site — `buildRegisterContext`'s callers decide their own
322	 * element subset directly). */
323	export interface RegisterContextOptions {
324	  prefix?: string | null;
325	  locale?: string;
326	  strings?: Partial<WebComponentStrings>;
327	  dir?: "ltr" | "rtl";
328	}
