346	  options: RegisterContextOptions,
347	  target: ElementRegistry,
348	  resolveIconSvg: (name: string) => string,
349	): RegisterContext {
350	  // Tag prefix: a valid non-empty string overrides the default; anything else (empty, whitespace, null,
351	  // omitted) falls back to `instui`. A prefix is always applied because a custom-element name MUST contain
352	  // a hyphen — `<icon>` is invalid, `<instui-icon>`/`<x-icon>` are not. The inlined `.instui-*` CSS classes
353	  // are an internal detail and are NOT affected by this — only the custom-element tag name.
354	  const prefix = resolvePrefix(options.prefix);
355	  const tag = (base: string): string => `${prefix}-${base}`;
356	  // Route every internal `registry.get`/`define` (all keyed on the canonical `instui-<base>` names)
357	  // through the active prefix.
358	  const registry = makeRegistry(target, tag);
359	
360	  // The shadow-DOM CSS is built with the default `instui` prefix so it matches the `instui-*` markup
361	  // in each element (the builders drop the prefix on a falsy value).
362	  const I = { prefix: "instui" } as const;
363	
364	  // The calendar and date picker drive navigation with the Invoker Commands API. `onCommand` routes a
365	  // target's `command` events to a handler; where the API is unavailable it delegates clicks on the
366	  // target's own `command`/`commandfor` buttons instead, so the buttons keep working everywhere.
367	  const INVOKER_SUPPORTED =
368	    typeof HTMLButtonElement !== "undefined" && "command" in HTMLButtonElement.prototype;
369	  const onCommand = makeOnCommand(INVOKER_SUPPORTED);
370	  const wrapper = makeWrapper(registry);
371	
372	  const locale = options.locale ?? "en";
373	  const dir = options.dir ?? "ltr";
374	  const strings = options.strings
375	    ? makeStrings(locale, options.strings)
376	    : locale === "en"
377	      ? ENGLISH_STRINGS
378	      : makeStrings(locale);
379	  const firstDay = resolveFirstDay(locale);
380	
381	  return {
382	    registry,
383	    tag,
384	    I,
385	    invokerSupported: INVOKER_SUPPORTED,
386	    onCommand,
387	    wrapper,
388	    variantClass,
389	    iconSvg: resolveIconSvg,
390	    locale,
391	    dir,
