402	 * @param options - `prefix` sets the tag prefix, mirroring the CSS layer: pass a non-empty string like
403	 *   `x` for `<x-icon>`. A prefix is always applied (a custom-element name must contain a hyphen), so an
404	 *   omitted, empty, or nullish prefix falls back to the default `instui` (`<instui-icon>`). `only` limits
405	 *   registration to a subset of the `ELEMENTS` base names — its nested render dependencies are pulled in
406	 *   automatically, so `{ only: ["date-time-input"] }` also defines `date-input` and `calendar`. Omit
407	 *   `only` to register every element (the default).
408	 *
409	 * @example
410	 * ```ts
411	 * import { register } from "@pantoken/web-components";
412	 * import "@pantoken/css"; // defines the --instui-* custom properties the elements read
413	 *
414	 * register(); // <instui-button>, <instui-icon>, …
415	 * register(customElements, { prefix: "x" }); // <x-button>, <x-icon>, …
416	 * register(customElements, { only: ["button", "alert"] }); // just those two
417	 * register(customElements, { locale: "hu", strings: { back: "Vissza" } }); // localized
418	 * ```
419	 */
420	export function register(
421	  target: ElementRegistry | undefined = globalThis.customElements,
422	  options: RegisterContextOptions & { only?: readonly string[] } = {},
423	): void {
424	  if (!target || typeof HTMLElement === "undefined") return;
425	
426	  // When `only` is given, expand it through the nested-render dependencies and define just that set;
427	  // otherwise define every element. The canonical `DEFINITIONS` order is preserved either way, so a
428	  // nested dependency is always defined before the element that renders it.
429	  const wanted = options.only ? withNestedDeps(options.only) : null;
430	
431	  const ctx = buildRegisterContext(options, target, iconSvg);
432	
433	  for (const def of DEFINITIONS) {
434	    if (wanted && !wanted.has(def.name)) continue;
435	    def.define(ctx);
436	  }
437	}
438	
439	// Auto-register in the browser; a no-op everywhere else.
440	register();
