1	// The docs site is themed with pantoken's own output: the full @property token sheet from
2	// @pantoken/css, then the @pantoken/vitepress bridge that maps VitePress's --vp-* variables onto
3	// var(--instui-*). The site you're reading is a live demo of the VitePress renderer.
4	import type { Theme } from "vitepress";
5	import DefaultTheme from "vitepress/theme";
6	// The multi-theme token sheet (rebrand default + canvas/canvasHighContrast under
7	// `:root[data-pantoken-theme]`), generated by `scripts/site-themes.ts`. The palette selector in the
8	// nav toggles the attribute to re-theme the whole site. Replaces the single-theme @pantoken/css sheet.
9	import "./generated/site-themes.css";
10	import "@pantoken/vitepress/custom.css";
11	import "@pantoken/vitepress/components.css";
12	// The docs-only multi-theme component sheet: the rebrand rules unscoped (byte-for-byte the shipped
13	// `@pantoken/components/components.css`) plus the canvas/canvasHighContrast rules scoped under
14	// `:root[data-pantoken-theme="…"]`, generated by `scripts/components-sheet.ts`. The shipped sheet is
15	// lowered to one theme, so its `@media (--theme-*)` overrides are pruned; this restores them so the
16	// inline CSS-API `@example` previews re-theme on the attribute toggle. Mirrors site-themes.css above.
17	import "./generated/components.css";
18	// Import the utility + icon sheets from `formats/components/generated/` (source-derived, regenerated by
19	// the orchestrator cascade and bridged into HMR via `outputWatchPaths`) rather than
20	// `@pantoken/components/*` (which resolves to `dist`, only rebuilt by the nested-forbidden `vp pack`).
21	// This keeps utility/icon edits live during docs:dev. Fonts stay on the shipped sheet — stable
22	// @font-face rules whose url()s resolve against the packaged assets/fonts.
23	import "../../../formats/components/generated/utilities.css";
24	import "../../../formats/components/generated/icons.css";
25	import "@pantoken/components/fonts.css";
26	import VitePressMermaid from "../plugins/vitepress-mermaid/index.vue";
27	import CdnPicker from "./components/CdnPicker.vue";
28	import CdnPickerPage from "./components/CdnPickerPage.vue";
29	// Import register() from the web-components SOURCE, not `@pantoken/web-components` (dist). The dist
30	// bundle is only rebuilt by `vp pack`, which can't run nested under vitepress — so a package import
31	// would freeze element behaviour + shadow CSS at the last pack. The source graph is Node-free (no
32	// node:/postcss/@cssdoc value imports) and needs no codegen: elements get CSS via Vite `?inline` and
33	// `@pantoken/components` *Css() functions, so Vite hot-reloads element `.ts` + co-located `.css` edits
34	// directly. register() is idempotent (it skips already-defined tags), so the barrel's own load-time
35	// register() plus the enhanceApp call below are safe.
36	// Extensionless (this file is type-checked; an explicit `.ts` needs allowImportingTsExtensions). Vite
37	// resolves it to src/index.ts at build/dev time.
38	import { register as registerWebComponents } from "../../../renderers/web-components/src/index";
39	import "@pantoken/demo/demo.css";
40	// `.instui-card` — the shared surface for the in-page CSS-API `@example` previews (`.css-example`) and
41	// the self-hosted demos. A static asset (not generated); the runner iframe loads the same file via ?css=.
42	import "@pantoken/demo/card.css";
43	import "./pantoken.css";
44	import Layout from "./Layout.vue";
45	import { applyTheme, getStoredTheme } from "./theme";
46	
47	/** Reply to a booting runner with the stored theme, targeting the frame's own origin. */
48	function replyWithTheme(event: MessageEvent): void {
49	  // "*" only for an opaque sandboxed frame, which can't match a specific target origin.
50	  (event.source as Window | null)?.postMessage(
51	    { type: "pantoken-demo-theme", theme: getStoredTheme() },
52	    event.origin === "null" ? "*" : event.origin,
53	  );
54	}
55	
56	/** Set the iframe (matched by its source window) to the height its runner reported. */
57	function applyRunnerSize(event: MessageEvent, height: number): void {
58	  const frame = [...document.querySelectorAll<HTMLIFrameElement>(".pantoken-demo__frame")].find(
59	    (f) => f.contentWindow === event.source,
60	  );
61	  if (frame) frame.style.height = `${height}px`;
62	}
63	
64	/** Demo message payloads accepted from runner iframes. */
65	type DemoMessage =
66	  | { type: "pantoken-demo-request-theme" }
67	  | { type: "pantoken-demo-size"; height: number };
68	
69	/** Accept same-origin posts plus opaque sandboxed (`null`) runner posts. */
70	function isTrustedDemoOrigin(origin: string): boolean {
71	  return origin === window.location.origin || origin === "null";
72	}
73	
74	/** Coerce unknown data into a loose payload object when possible. */
75	function asDemoPayload(data: unknown): { type?: string; height?: unknown } | null {
76	  if (!data || typeof data !== "object") return null;
77	  return data as { type?: string; height?: unknown };
78	}
79	
80	/** Parse a validated demo-size message payload. */
81	function asSizeMessage(payload: { type?: string; height?: unknown }): DemoMessage | null {
82	  if (payload.type !== "pantoken-demo-size" || typeof payload.height !== "number") return null;
83	  return { type: payload.type, height: payload.height };
84	}
85	
86	/** Narrow unknown postMessage payloads to known runner message variants. */
87	function asDemoMessage(data: unknown): DemoMessage | null {
88	  const payload = asDemoPayload(data);
89	  if (!payload) return null;
90	  if (payload.type === "pantoken-demo-request-theme") return { type: payload.type };
91	  return asSizeMessage(payload);
92	}
93	
94	/** Dispatch one validated runner message. */
95	function handleDemoMessage(event: MessageEvent, message: DemoMessage): void {
96	  if (message.type === "pantoken-demo-request-theme") {
97	    replyWithTheme(event);
98	    return;
99	  }
100	  applyRunnerSize(event, message.height);
101	}
102	
103	/**
104	 * Relay theme/size messages between the page and its demo runners. Only same-origin (or opaque
105	 * "null"-origin sandboxed) posts are accepted, so another page can't spoof size/theme messages.
106	 */
107	function relayDemoMessage(event: MessageEvent): void {
108	  if (!isTrustedDemoOrigin(event.origin)) return;
109	  const message = asDemoMessage(event.data);
110	  if (!message) return;
111	  handleDemoMessage(event, message);
112	}
113	
114	export default {
115	  extends: DefaultTheme,
116	  Layout,
117	  enhanceApp(ctx) {
118	    DefaultTheme.enhanceApp?.(ctx);
119	    ctx.app.component("vitepress-mermaid", VitePressMermaid);
120	    // The interactive CDN combine-URL builder used on the CDN guide page (docs/guide/cdn.md).
121	    ctx.app.component("CdnPicker", CdnPicker);
122	    ctx.app.component("CdnPickerPage", CdnPickerPage);
123	
124	    // Register the pantoken custom elements so the `@example` blocks on the web-components API pages
125	    // render live (the elements inline their own CSS; the token sheet above colours them). A no-op
126	    // during SSR — it early-returns without a DOM.
127	    registerWebComponents();
128	
129	    // Wire the demo iframes: apply the persisted theme on load, then relay theme + size messages.
130	    if (typeof document !== "undefined") {
131	      // The head script already set the theme attribute (no flash); this reconciles the light/dark
132	      // class and broadcasts the theme to any demos already on the page.
133	      applyTheme(getStoredTheme());
134	
135	      // The runner (inside each figure's iframe) posts the height it wants — its toolbar plus the body
136	      // (which hugs the demo by default, capped at 30rem, or whatever height the reader dragged it to).
137	      // Match the message to its frame by source window and set the height so the iframe mirrors it.
138	      window.addEventListener("message", relayDemoMessage);
139	    }
140	  },
141	} satisfies Theme;
