2	   whole site. The token carries its own fallback chain: Atkinson, then system-ui. */
3	:root {
4	  /* Vite's production CSS transform lowers light-dark() to scheme helper variables. Give that
5	     transform an explicit light default to pair with the dark override below; without it,
6	     both lowered branches remain active in light mode and concatenate into invalid colours. */
7	  color-scheme: light;
8	
9	  --vp-c-bg: var(--instui-color-background-container);
