input.text:
(() => {
  const btn = document.querySelector('.vp-doc [class*="language-"] > button.copy');
  let el = btn;
  const chain = [];
  while (el) {
    const cs = getComputedStyle(el);
    chain.push({tag: el.tagName, cls: el.className, color: cs.color});
    el = el.parentElement;
    if (chain.length > 10) break;
  }
  return JSON.stringify(chain, null, 1);
})()

