179	const si = "npm/@pantoken/plugin-simple-icons/dist";
180	
181	const combineUrl = computed(() => {
182	  const files: string[] = [];
183	  if (allInstuiSelected.value) {
184	    files.push(`${c}/icons.css`);
185	  } else {
186	    for (const name of selectedInstui.value) files.push(`${c}/icons/${name}.css`);
187	  }
188	  for (const slug of selectedSimple.value) files.push(`${si}/icons/${slug}.css`);
189	  return files.length === 0 ? null : `https://cdn.jsdelivr.net/combine/${files.join(",")}`;
190	});
191	
192	const esmSnippet = computed(() => {
193	  const lines: string[] = [];
194	  if (allInstuiSelected.value) {
195	    lines.push(`import "https://esm.sh/@pantoken/components/icons.css";`);
196	  } else {
197	    for (const name of selectedInstui.value) {
198	      lines.push(`import "https://esm.sh/@pantoken/components/icons/${name}.css";`);
199	    }
200	  }
201	  for (const slug of selectedSimple.value) {
202	    lines.push(`import "https://esm.sh/@pantoken/plugin-simple-icons/icons/${slug}.css";`);
203	  }
204	  return lines.length === 0 ? null : lines.join("\n");
205	});
206	
207	const output = computed(() => {
208	  if (format.value === "esm") return esmSnippet.value ?? "";
209	  const url = combineUrl.value;
210	  if (!url) return "";
211	  return format.value === "link"
212	    ? `<link rel="stylesheet" href="${url}">`
213	    : `@import url("${url}");`;
214	});
215	</script>

