(async () => {
  const allBox = document.querySelector('.icon-picker__grid input[type=checkbox]');
  // wait for both manifests to load (checkbox disabled until then)
  for (let i = 0; i < 50 && allBox.disabled; i++) await new Promise(r => setTimeout(r, 100));
  allBox.click();
  await new Promise(r => setTimeout(r, 200));
  const pre = document.querySelector('.icon-picker .picker-output pre code');
  return pre ? pre.textContent : 'not found';
})()

(() => {
  const tabs = document.querySelectorAll('.icon-picker .picker-output .tab');
  [...tabs].find(t => t.textContent.trim() === 'ESM snippet').click();
  return 'clicked';
})()

(async () => {
  await new Promise(r => setTimeout(r, 200));
  const pre = document.querySelector('.icon-picker .picker-output pre code');
  return pre ? pre.textContent : 'not found';
})()

(async () => {
  const allBox = document.querySelector('.icon-picker__grid input[type=checkbox]');
  allBox.click(); // uncheck all
  await new Promise(r => setTimeout(r, 100));
  const items = [...document.querySelectorAll('.icon-picker__item input[type=checkbox]')];
  // pick first InstUI and first Simple icon
  items[0].click();
  const simpleItem = items.find(i => i.closest('.icon-picker__item')?.querySelector('img'));
  simpleItem.click();
  await new Promise(r => setTimeout(r, 200));
  const pre = document.querySelector('.icon-picker .picker-output pre code');
  return pre ? pre.textContent : 'not found';
})()

